type Lesson = { id:number; title:string; inquiry:string; experience:string; evidence:string; choice:string };
const starterLessons:Lesson[]=[{id:1,title:'Provocation and prior thinking',inquiry:'What do we already think we know? What puzzles us?',experience:'Offer a surprising object, image, local example or experience. Capture initial ideas without correcting them too quickly.',evidence:'Notice students’ questions, assumptions and vocabulary.',choice:'Students share questions in a way that works for them.'},{id:2,title:'Explore a line of inquiry',inquiry:'What do we need to find out?',experience:'Plan an observation, source investigation, interview or hands-on exploration connected to a line of inquiry.',evidence:'Collect observations, student explanations and emerging questions.',choice:'Students suggest sources, roles or ways to investigate.'},{id:3,title:'Connect and rethink',inquiry:'How does this connect to our central idea?',experience:'Compare findings, discuss different perspectives and revisit the class’s first ideas.',evidence:'Look for explanations that use evidence and conceptual language.',choice:'Students choose a finding or question to explore further.'},{id:4,title:'Apply understanding',inquiry:'How can we use what we have learned in a new situation?',experience:'Offer a transfer task, design challenge, case study or real-world problem.',evidence:'Listen for independent reasoning and application, not just recall.',choice:'Students choose an approach or format for showing understanding.'},{id:5,title:'Reflect and consider action',inquiry:'What has changed in our thinking, and what might we do next?',experience:'Return to initial questions, share learning and consider realistic, responsible action.',evidence:'Compare initial and current thinking; gather reflections and next questions.',choice:'Students identify meaningful next steps or actions.'}];
